async function main() {
  console.log("🌱 seeding…");

  // -- demo users -----------------------------------------------------------
  const admin = await upsertUser("admin@svetlana.example", "Администратор", "ADMIN");
  const buyer = await upsertUser("anna@svetlana.example", "Анна Иванова", "BUYER");
  const buyer2 = await upsertUser("pavel@svetlana.example", "Павел Смирнов", "BUYER");

  const sellerUsers = {
    "techno-aurora": await upsertUser("seller1@svetlana.example", "ИП ТехноАврора", "SELLER"),
    "mobile-market": await upsertUser("seller2@svetlana.example", "ООО МобайлМаркет", "SELLER"),
    "home-comfort": await upsertUser("seller3@svetlana.example", "Самозанятая — ДомУютно", "SELLER"),
    "style-lab": await upsertUser("seller4@svetlana.example", "ИП СтайлЛаб", "SELLER"),
    "master-pro": await upsertUser("seller5@svetlana.example", "ООО МастерПро", "SELLER"),
    "design-studio": await upsertUser("seller6@svetlana.example", "Студия Дизайна", "SELLER"),
  };

  const sellerMeta: Record<string, {
    type: string; inn: string; ogrn?: string; display: string; description: string;
    identity: string; business: string; npd: string;
  }> = {
    "techno-aurora": { type: "IP", inn: "770123456789", ogrn: "304770123456789", display: "ТехноАврора", description: "Ноутбуки и компьютерная техника. Официальный дилер.", identity: "VERIFIED", business: "VERIFIED", npd: "UNVERIFIED" },
    "mobile-market": { type: "COMPANY", inn: "7709876543210", ogrn: "1127746123456", display: "МобайлМаркет", description: "Смартфоны, аудио и аксессуары. Магазин на маркетплейсе с 2019 года.", identity: "VERIFIED", business: "VERIFIED", npd: "UNVERIFIED" },
    "home-comfort": { type: "SELF_EMPLOYED", inn: "550123456789", display: "ДомУютно", description: "Товары для дома ручной работы и декор для интерьера.", identity: "VERIFIED", business: "UNVERIFIED", npd: "VERIFIED" },
    "style-lab": { type: "IP", inn: "770555123456", ogrn: "315774600012345", display: "СтайлЛаб", description: "Одежда и аксессуары собственного производства.", identity: "VERIFIED", business: "VERIFIED", npd: "UNVERIFIED" },
    "master-pro": { type: "COMPANY", inn: "7701112223330", ogrn: "1107746555666", display: "МастерПро", description: "Инструмент и ремонтные услуги. Гарантия на работы.", identity: "VERIFIED", business: "VERIFIED", npd: "UNVERIFIED" },
    "design-studio": { type: "IP", inn: "770999888777", ogrn: "3187746000999", display: "Студия Дизайна", description: "Дизайн-проекты интерьеров и 3D-визуализация.", identity: "VERIFIED", business: "VERIFIED", npd: "UNVERIFIED" },
  };

  for (const [slug, user] of Object.entries(sellerUsers)) {
    const meta = sellerMeta[slug];
    await prisma.sellerProfile.upsert({
      where: { slug },
      create: {
        userId: user.id,
        slug,
        displayName: meta.display,
        description: meta.description,
        sellerType: meta.type,
        inn: meta.inn,
        ogrn: meta.ogrn,
        identityStatus: meta.identity,
        businessStatus: meta.business,
        npdStatus: meta.npd,
        isActivated: true,
        trustSignals: JSON.stringify({
          accountAgeDays: 1200,
          ordersFulfilled: Math.floor(Math.random() * 400) + 20,
          avgRating: 4.6,
          returnRate: 0.02,
          disputeRate: 0.01,
        }),
      },
      update: {},
    });
  }

  // -- categories -----------------------------------------------------------
  for (const cat of CATEGORIES) {
    await prisma.category.upsert({
      where: { slug: cat.slug },
      create: { slug: cat.slug, name: cat.name },
      update: {},
    });
    for (const child of cat.children ?? []) {
      await prisma.category.upsert({
        where: { slug: child.slug },
        create: { slug: child.slug, name: child.name, parentId: (await prisma.category.findFirst({ where: { slug: cat.slug } }))!.id },
        update: {},
      });
    }
  }

  // -- products -------------------------------------------------------------
  for (const p of PRODUCTS) {
    const seller = (await prisma.sellerProfile.findFirst({ where: { slug: p.sellerSlug } }))!;
    const category = await prisma.category.findFirst({ where: { slug: p.category } });
    const existing = await prisma.product.findFirst({ where: { sku: p.sku } });
    if (existing) {
      await prisma.product.update({
        where: { id: existing.id },
        data: {
          title: p.title, description: p.description, priceKopecks: p.price * 100,
          oldPriceKopecks: p.oldPrice ? p.oldPrice * 100 : null,
          attributes: JSON.stringify(p.attributes), keywords: JSON.stringify(p.keywords),
          categoryId: category?.id, status: "ACTIVE",
        },
      });
      continue;
    }
    const product = await prisma.product.create({
      data: {
        sellerId: seller.id,
        categoryId: category?.id,
        sku: p.sku,
        title: p.title,
        description: p.description,
        attributes: JSON.stringify(p.attributes),
        keywords: JSON.stringify(p.keywords),
        seoSlug: `${p.sku.toLowerCase()}-svetlana`,
        status: "ACTIVE",
        priceKopecks: p.price * 100,
        oldPriceKopecks: p.oldPrice ? p.oldPrice * 100 : null,
        rating: p.rating,
        views: Math.floor(Math.random() * 800) + 50,
      },
    });
    await prisma.productImage.create({
      data: { productId: product.id, url: p.image, alt: p.title, isPrimary: true, position: 0 },
    });
    await prisma.inventory.create({
      data: {
        productId: product.id,
        quantity: p.quantity,
        availability: p.quantity > 10 ? "AVAILABLE" : "LIMITED",
        confirmedBySeller: true,
        confirmedAt: new Date(),
        saleUntil: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
        autoExtend: true,
      },
    });
    await prisma.listing.create({
      data: {
        productId: product.id,
        publishedAt: new Date(),
        expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
        isLive: true,
      },
    });
    await prisma.listingHistory.create({
      data: { productId: product.id, action: "CREATED", change: JSON.stringify({ price: p.price }), note: "seed" },
    });
    for (const r of p.reviews) {
      await prisma.review.create({
        data: {
          productId: product.id,
          authorId: buyer.id,
          rating: r.rating,
          body: r.body,
          verifiedPurchase: true,
          aiAnalysis: JSON.stringify({ sentiment: r.rating >= 5 ? "positive" : "neutral", themes: [] }),
        },
      });
    }
    await recomputeProductRating(product.id);
  }

  // -- a buyer with a wishlist, favorites and a completed order -------------
  const phone = await prisma.product.findFirst({ where: { sku: "PH-001" } });
  const headphones = await prisma.product.findFirst({ where: { sku: "AU-001" } });
  const vase = await prisma.product.findFirst({ where: { sku: "DC-001" } });
  if (phone) await prisma.favorite.create({ data: { userId: buyer.id, productId: phone.id } });
  if (vase) await prisma.favorite.create({ data: { userId: buyer.id, productId: vase.id } });

  const wishlist = await prisma.wishlist.create({
    data: { userId: buyer.id, name: "Подарки на Новый год", isPrivate: true },
  });
  if (headphones) {
    await prisma.wishlistItem.create({ data: { wishlistId: wishlist.id, userId: buyer.id, productId: headphones.id } });
  }

  // consents
  for (const type of ["PERSONAL_DATA", "AI_PERSONALIZATION", "AI_MEMORY", "COOKIES_STRICTLY_NECESSARY"]) {
    await prisma.consent.create({
      data: { userId: buyer.id, type, granted: true, grantedAt: new Date() },
    });
  }

  // memory
  await prisma.aiMemory.create({
    data: {
      userId: buyer.id,
      type: "PREFERENCE",
      key: "budget_range_rub",
      value: "5000-15000",
      source: "user_stated",
    },
  });
  await prisma.aiMemory.create({
    data: {
      userId: buyer.id,
      type: "FACT",
      key: "prefers_delivery_pickup",
      value: "true",
      source: "user_stated",
    },
  });

  // relationships with a pending confirmation
  const rel = await prisma.relationship.create({
    data: {
      fromUserId: buyer.id,
      toUserId: buyer2.id,
      type: "FRIEND",
      status: "PENDING_CONFIRMATION",
      source: "manual",
    },
  });
  await prisma.relationshipConfirmation.create({
    data: {
      relationshipId: rel.id,
      requestedById: buyer.id,
      token: "demo-confirmation-token",
    },
  });

  // a gift event
  await prisma.giftEvent.create({
    data: {
      creatorId: buyer.id,
      recipientName: "Мама",
      recipientRelationship: "PARENT",
      occasion: "birthday",
      eventDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000),
      budgetKopecks: 10000 * 100,
      interests: JSON.stringify(["цветы", "дом", "кулинария"]),
      status: "ACTIVE",
      stealthMode: true,
    },
  });

  // delivery providers
  for (const [key, name] of [
    ["sandbox_courier", "Курьерская служба (sandbox)"],
    ["sandbox_pickup", "Пункты выдачи (sandbox)"],
    ["seller_own", "Доставка продавца"],
  ]) {
    await prisma.deliveryProvider.create({
      data: {
        adapterKey: key,
        name,
        isEnabled: true,
        supportsPickupPoints: key === "sandbox_pickup",
        supportsCourier: key !== "sandbox_pickup",
      },
    });
  }

  // seller workflow automation
  const masterSeller = await prisma.sellerProfile.findFirst({ where: { slug: "master-pro" } });
  if (masterSeller) {
    await prisma.workflowRule.create({
      data: {
        sellerId: masterSeller.id,
        trigger: "inventory_low",
        condition: JSON.stringify({ threshold: 10 }),
        action: "notify_seller",
        isEnabled: true,
      },
    });
  }

  console.log("✅ seed complete");
  console.log(`   users: ${await prisma.user.count()}`);
  console.log(`   sellers: ${await prisma.sellerProfile.count()}`);
  console.log(`   products: ${await prisma.product.count()}`);
  console.log(`   reviews: ${await prisma.review.count()}`);
  console.log(`   demo password: ${DEMO_PASSWORD}`);
}

async function upsertUser(email: string, name: string, role: string) {
  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) return existing;
  const user = await prisma.user.create({
    data: { email, name, role, passwordHash: await hashPassword(DEMO_PASSWORD) },
  });
  await prisma.profile.create({ data: { userId: user.id, displayName: name } });
  return user;
}

async function recomputeProductRating(productId: string) {
  const agg = await prisma.review.aggregate({
    where: { productId, isHidden: false },
    _avg: { rating: true },
    _count: true,
  });
  await prisma.product.update({
    where: { id: productId },
    data: {
      rating: Math.round((agg._avg.rating ?? 0) * 10) / 10,
      reviewsCount: agg._count,
    },
  });
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
